from collections import Counter

_RANKS = {rank: value for value, rank in enumerate("23456789TJQKA", start=2)}


def _score(hand):
    cards = hand.split()
    ranks = sorted((_RANKS[card[:-1]] for card in cards), reverse=True)
    counts = Counter(ranks)
    is_flush = len({card[-1] for card in cards}) == 1

    straight_high = None
    if len(counts) == 5:
        if max(ranks) - min(ranks) == 4:
            straight_high = max(ranks)
        elif set(ranks) == {14, 5, 4, 3, 2}:  # ace-low straight
            straight_high = 5

    if straight_high is not None:
        category = 8 if is_flush else 4
        return (category, straight_high)

    ordered = sorted(counts.items(), key=lambda item: (item[1], item[0]), reverse=True)
    tiebreak = [rank for rank, _ in ordered]

    if is_flush:
        category = 5
    else:
        shape = tuple(sorted(counts.values(), reverse=True))
        category = {
            (4, 1): 7,
            (3, 2): 6,
            (3, 1, 1): 3,
            (2, 2, 1): 2,
            (2, 1, 1, 1): 1,
            (1, 1, 1, 1, 1): 0,
        }[shape]

    return (category, *tiebreak)


def best_hands(hands):
    scored = [(_score(hand), hand) for hand in hands]
    best = max(score for score, _ in scored)
    return [hand for score, hand in scored if score == best]

